#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

long long modExp(long long base, int exp) {
    long long result = 1;
    long long cur = base % MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * cur) % MOD;
        cur = (cur * cur) % MOD;
        exp >>= 1;
    }
    return result;
}

vector<vector<long long>> matMult(const vector<vector<long long>>& a, const vector<vector<long long>>& b) {
    int n = a.size();
    int m = b[0].size();
    int k = a[0].size();
    vector<vector<long long>> c(n, vector<long long>(m, 0));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            for (int t = 0; t < k; t++) {
                c[i][j] = (c[i][j] + a[i][t] * b[t][j]) % MOD;
            }
        }
    }
    return c;
}

vector<vector<long long>> matExp(vector<vector<long long>> m, int e) {
    int size = m.size();
    vector<vector<long long>> result(size, vector<long long>(size, 0));
    for (int i = 0; i < size; i++) result[i][i] = 1;
    while (e > 0) {
        if (e & 1) result = matMult(result, m);
        m = matMult(m, m);
        e >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, l, r;
    cin >> n >> m >> l >> r;

    if (n % 2 == 1 && m % 2 == 1) {
        long long base = (r - l + 1) % MOD;
        long long expN = modExp(base, n);
        long long ans = modExp(expN, m);
        cout << ans << "\n";
        return 0;
    }

    int even = r / 2 - (l + 1) / 2 + 1;
    int odd = (r - l + 1) - even;

    vector<vector<long long>> mat = {{even, odd}, {odd, even}};
    mat = matExp(mat, n);
    mat = matExp(mat, m);
    cout << mat[0][0] % MOD << "\n";

    return 0;
}
